def merge_intervals(intervals):
    intervals.sort()
    merged = []
    for interval in intervals:
        if not merged or merged[-1][1] < interval[0]:
            merged.append(interval)
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])
    return merged

def first_unique_index(text):
    char_count = {}
    for i, char in enumerate(text):
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    for i, char in enumerate(text):
        if char_count[char] == 1:
            return i
    return -1

def topo_sort(nodes, edges):
    # 构建图
    graph = {node: [] for node in nodes}
    for u, v in edges:
        if u not in nodes or v not in nodes:
            raise ValueError("未知节点")
        graph[u].append(v)

    # 检查环
    visited = set()
    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor)
    for node in nodes:
        dfs(node)

    # 拓扑排序
    stack = []
    def dfs2(node):
        if node in stack:
            return
        for neighbor in graph[node]:
            dfs2(neighbor)
        stack.append(node)
    for node in nodes:
        dfs2(node)

    # 反转顺序
    stack.reverse()
    return stack

def evaluate_rpn(tokens):
    stack = []
    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            stack.append(int(token))
        elif token in '+-*/':
            if len(stack) < 2:
                raise ValueError('Invalid expression')
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ValueError('Division by zero')
                stack.append(int(a / b))
        else:
            raise ValueError('Invalid token')
    if len(stack) != 1:
        raise ValueError('Invalid expression')
    return stack[0]

def sliding_window_max(nums, k):
    if k <= 0 or k > len(nums):
        raise ValueError("k must be positive and less than or equal to the length of nums")
    deque = collections.deque()
    res = []
    for i, num in enumerate(nums):
        while deque and nums[deque[-1]] <= num:
            deque.pop()
        deque.append(i)
        if deque[0] == i - k:
            deque.popleft()
        if i >= k - 1:
            res.append(nums[deque[0]])
    return res
